        input
            .default(default.clone())
            .interact_on(term)
            .map_err(|e| {
                term.show_cursor().ok();
                map_dialoguer_err(e)
            })?
    } else {
        input.interact_on(term).map_err(|e| {
            term.show_cursor().ok();
            map_dialoguer_err(e)
        })?
    };

    Ok(PromptResult::String(result))
}

