//! Interactive prompts.

use console::{measure_text_width, style, Key, Style, Term};
use dialoguer::theme::ColorfulTheme;
use dialoguer::{Confirm, Input, MultiSelect, Select};

use crate::error::{BivvyError, Result};

use super::{Prompt, PromptOption, PromptResult, PromptType};

/// Convert dialoguer errors to BivvyError.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    BivvyError::Io(e.into())
}

/// Dialoguer theme without the default yellow `?` prefix.
fn prompt_theme() -> ColorfulTheme {
    ColorfulTheme {
        prompt_prefix: style("".to_string()),
        ..ColorfulTheme::default()
    }
}

/// Prompt the user for input.
pub fn prompt_user(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    match &prompt.prompt_type {
        PromptType::Confirm => prompt_confirm(prompt, term),
        PromptType::Input => prompt_input(prompt, term),
        PromptType::Select { options } => prompt_select(prompt, options, term),
        PromptType::MultiSelect { options } => prompt_multiselect(prompt, options, term),
    }
}

fn prompt_confirm(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    let default = prompt
        .default
        .as_ref()
        .map(|s| s.to_lowercase() == "true" || s == "y" || s == "yes")
        .unwrap_or(true);

    let result = Confirm::new()
        .with_prompt(&prompt.question)
        .default(default)
        .interact_on(term)
        .map_err(|e| {
            term.show_cursor().ok();
            map_dialoguer_err(e)
        })?;

    Ok(PromptResult::Bool(result))
}

fn prompt_input(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    let input = Input::<String>::new().with_prompt(&prompt.question);

    let result: String = if let Some(default) = &prompt.default {
        input
            .default(default.clone())
            .interact_on(term)
            .map_err(|e| {
                term.show_cursor().ok();
                map_dialoguer_err(e)
            })?
    } else {
        input.interact_on(term).map_err(|e| {
            term.show_cursor().ok();
            map_dialoguer_err(e)
        })?
    };

    Ok(PromptResult::String(result))
}

/// Dialoguer theme for general select prompts with `›`/`·` indicators.
fn select_theme() -> ColorfulTheme {
    ColorfulTheme {
        prompt_prefix: style("".to_string()),
        prompt_suffix: style("".to_string()),
        success_prefix: style("".to_string()),
        success_suffix: style("·".to_string()).for_stderr().dim(),
        active_item_prefix: style("›".to_string()).for_stderr().bold(),
        inactive_item_prefix: style("·".to_string()).for_stderr().dim(),
        active_item_style: Style::new().for_stderr().bold(),
        inactive_item_style: Style::new().for_stderr().dim(),
        values_style: Style::new().for_stderr().bold(),
        ..ColorfulTheme::default()
    }
}

/// Check if options form a yes/no pair.
fn is_yes_no(options: &[PromptOption]) -> bool {
    options.len() == 2
        && options.iter().any(|o| o.value == "yes")
        && options.iter().any(|o| o.value == "no")
}

fn prompt_select(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
    // Use custom yes/no prompt for y/n keyboard shortcut support
    if is_yes_no(options) {
        return prompt_yes_no(prompt, options, term);
    }

    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();

    let default_idx = prompt
        .default
        .as_ref()
        .and_then(|d| options.iter().position(|o| o.value == *d))
        .unwrap_or(0);

    let selection = Select::with_theme(&select_theme())
        .with_prompt(&prompt.question)
        .items(&labels)
        .default(default_idx)
        .interact_on(term)
        .map_err(|e| {
            term.show_cursor().ok();
            map_dialoguer_err(e)
        })?;

    Ok(PromptResult::String(options[selection].value.clone()))
}

/// Result of processing a key press in the yes/no prompt.
enum YesNoAction {
    /// User chose an option at the given index.
    Choose(usize),
    /// Move selection forward.
    Next,
    /// Move selection backward.
    Prev,
    /// Unrecognized key, do nothing.
    Ignore,
}

/// Map a key press to an action in the yes/no prompt.
fn yes_no_key_action(
    key: &Key,
    options: &[PromptOption],
    sel: usize,
    default_idx: usize,
) -> YesNoAction {
    match key {
        Key::Char('y') | Key::Char('Y') => {
            match options.iter().position(|o| o.value == "yes") {
                Some(idx) => YesNoAction::Choose(idx),
                None => YesNoAction::Ignore,
            }
        }
        Key::Char('n') | Key::Char('N') => {
            match options.iter().position(|o| o.value == "no") {
                Some(idx) => YesNoAction::Choose(idx),
                None => YesNoAction::Ignore,
            }
        }
        Key::Char('\x04') => YesNoAction::Choose(default_idx),
        Key::Enter | Key::Char(' ') => YesNoAction::Choose(sel),
        Key::ArrowDown | Key::Tab | Key::Char('j') => YesNoAction::Next,
        Key::ArrowUp | Key::BackTab | Key::Char('k') => YesNoAction::Prev,
        _ => YesNoAction::Ignore,
    }
}

/// Custom yes/no prompt with `›`/`·` indicators and `y`/`n` keyboard shortcuts.
///
/// Renders options below the prompt question, indented to align with
/// the step name. Supports arrow keys, j/k, Enter/Space, y/n, and
/// Ctrl+D (selects default).
fn prompt_yes_no(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
    let default_idx = prompt
        .default
        .as_ref()
        .and_then(|d| options.iter().position(|o| o.value == *d))
        .unwrap_or(0);

    let mut sel = default_idx;

    // Calculate indent: measure the visible width of the question text
    // to find where `[n/t] ` ends. We use a heuristic: find the first `]`
    // and add 2 for `] `.
    let indent = measure_text_width(&prompt.question)
        .min(prompt.question.find(']').map(|i| i + 2).unwrap_or(6));
    let pad = " ".repeat(indent);

    let active_prefix = Style::new().bold();
    let active_style = Style::new().bold();
    let inactive_prefix = Style::new().dim();
    let inactive_style = Style::new().dim();

    // Write prompt question
    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
    term.hide_cursor().map_err(BivvyError::Io)?;

    loop {
        // Draw option lines
        for (i, opt) in options.iter().enumerate() {
            let line = if i == sel {
                format!(
                    "{}{} {}",
                    pad,
                    active_prefix.apply_to("›"),
                    active_style.apply_to(&opt.label)
                )
            } else {
                format!(
                    "{}{} {}",
                    pad,
                    inactive_prefix.apply_to("·"),
                    inactive_style.apply_to(&opt.label)
                )
            };
            term.write_line(&line).map_err(BivvyError::Io)?;
        }
        term.flush().map_err(BivvyError::Io)?;

        // Read key (handle EOF from Ctrl+D gracefully)
        let key = match term.read_key() {
            Ok(key) => key,
            Err(e) => {
                term.show_cursor().ok();
                return Err(BivvyError::Io(e));
            }
        };

        match yes_no_key_action(&key, options, sel, default_idx) {
            YesNoAction::Choose(idx) => {
                // Clear option lines
                term.clear_last_lines(options.len())
                    .map_err(BivvyError::Io)?;
                // Clear the prompt question line
                term.clear_last_lines(1).map_err(BivvyError::Io)?;
                // Re-print prompt with selection (show "yes" or "no")
                let answer_text = if options[idx].value == "yes" {
                    "yes"
                } else {
                    "no"
                };
                term.write_line(&format!(
                    "{} {}",
                    prompt.question,
                    Style::new().bold().apply_to(answer_text)
                ))
                .map_err(BivvyError::Io)?;
                term.show_cursor().map_err(BivvyError::Io)?;

                return Ok(PromptResult::String(options[idx].value.clone()));
            }
            YesNoAction::Next => {
                sel = (sel + 1) % options.len();
            }
            YesNoAction::Prev => {
                sel = (sel + options.len() - 1) % options.len();
            }
            YesNoAction::Ignore => {}
        }

        // Clear option lines for redraw
        term.clear_last_lines(options.len())
            .map_err(BivvyError::Io)?;
    }
}

fn prompt_multiselect(
    prompt: &Prompt,
    options: &[PromptOption],
    term: &Term,
) -> Result<PromptResult> {
    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();

    let default_values: Vec<&str> = prompt
        .default
        .as_deref()
        .map(|d| d.split(',').collect())
        .unwrap_or_default();
    let defaults: Vec<bool> = options
        .iter()
        .map(|o| default_values.contains(&o.value.as_str()))
        .collect();

    let selections = MultiSelect::with_theme(&prompt_theme())
        .with_prompt(&prompt.question)
        .items(&labels)
        .defaults(&defaults)
        .interact_on(term)
        .map_err(|e| {
            term.show_cursor().ok();
            map_dialoguer_err(e)
        })?;

    let values: Vec<String> = selections
        .iter()
        .map(|&i| options[i].value.clone())
        .collect();

    Ok(PromptResult::Strings(values))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn make_prompt(key: &str, prompt_type: PromptType, default: Option<&str>) -> Prompt {
        Prompt {
            key: key.to_string(),
            question: "Test question?".to_string(),
            prompt_type,
            default: default.map(String::from),
        }
    }

    #[test]
    fn prompt_creation() {
        let prompt = make_prompt("test", PromptType::Input, Some("default"));
        assert_eq!(prompt.key, "test");
        assert_eq!(prompt.default, Some("default".to_string()));
    }

    #[test]
    fn prompt_type_confirm_creation() {
        let prompt = make_prompt("confirm", PromptType::Confirm, None);
        assert!(matches!(prompt.prompt_type, PromptType::Confirm));
    }

    #[test]
    fn prompt_type_select_with_options() {
        let options = vec![
            PromptOption {
                label: "Option A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "Option B".to_string(),
                value: "b".to_string(),
            },
        ];
        let prompt = make_prompt(
            "select",
            PromptType::Select {
                options: options.clone(),
            },
            None,
        );
        if let PromptType::Select { options: stored } = prompt.prompt_type {
            assert_eq!(stored.len(), 2);
            assert_eq!(stored[0].value, "a");
        } else {
            panic!("Expected Select variant");
        }
    }

    #[test]
    fn prompt_type_multiselect_with_options() {
        let options = vec![PromptOption {
            label: "Feature 1".to_string(),
            value: "f1".to_string(),
        }];
        let prompt = make_prompt(
            "multi",
            PromptType::MultiSelect {
                options: options.clone(),
            },
            None,
        );
        if let PromptType::MultiSelect { options: stored } = prompt.prompt_type {
            assert_eq!(stored.len(), 1);
        } else {
            panic!("Expected MultiSelect variant");
        }
    }

    #[test]
    fn is_yes_no_returns_true_for_yes_no_options() {
        let options = vec![
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
        ];
        assert!(is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_true_regardless_of_order() {
        let options = vec![
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
        ];
        assert!(is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_false_for_other_options() {
        let options = vec![
            PromptOption {
                label: "Option A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "Option B".to_string(),
                value: "b".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_false_for_more_than_two() {
        let options = vec![
            PromptOption {
                label: "Yes".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Maybe".to_string(),
                value: "maybe".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

    #[test]
    fn select_theme_creates_without_panic() {
        let theme = select_theme();
        // Verify the theme object can be used (smoke test)
        drop(theme);
    }

    fn yes_no_options() -> Vec<PromptOption> {
        vec![
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
        ]
    }

    #[test]
    fn yes_no_key_action_y_chooses_yes() {
        let options = yes_no_options();
        let action = yes_no_key_action(&Key::Char('y'), &options, 1, 0);
        assert!(matches!(action, YesNoAction::Choose(0)));
    }

    #[test]
    fn yes_no_key_action_n_chooses_no() {
        let options = yes_no_options();
        let action = yes_no_key_action(&Key::Char('n'), &options, 0, 0);
        assert!(matches!(action, YesNoAction::Choose(1)));
    }

    #[test]
    fn yes_no_key_action_enter_chooses_current_selection() {
        let options = yes_no_options();
        let action = yes_no_key_action(&Key::Enter, &options, 1, 0);
        assert!(matches!(action, YesNoAction::Choose(1)));
    }

    #[test]
    fn yes_no_key_action_ctrl_d_chooses_default() {
        let options = yes_no_options();
        // default_idx=1 (no), sel=0 (yes) — Ctrl+D should pick default (no)
        let action = yes_no_key_action(&Key::Char('\x04'), &options, 0, 1);
        assert!(matches!(action, YesNoAction::Choose(1)));
    }

    #[test]
    fn yes_no_key_action_ctrl_d_chooses_default_yes() {
        let options = yes_no_options();
        // default_idx=0 (yes), sel=1 (no) — Ctrl+D should pick default (yes)
        let action = yes_no_key_action(&Key::Char('\x04'), &options, 1, 0);
        assert!(matches!(action, YesNoAction::Choose(0)));
    }

    #[test]
    fn yes_no_key_action_arrow_down_moves_next() {
        let options = yes_no_options();
        let action = yes_no_key_action(&Key::ArrowDown, &options, 0, 0);
        assert!(matches!(action, YesNoAction::Next));
    }

    #[test]
    fn yes_no_key_action_arrow_up_moves_prev() {
        let options = yes_no_options();
        let action = yes_no_key_action(&Key::ArrowUp, &options, 1, 0);
        assert!(matches!(action, YesNoAction::Prev));
    }

    #[test]
    fn yes_no_key_action_unknown_key_ignored() {
        let options = yes_no_options();
        let action = yes_no_key_action(&Key::Char('x'), &options, 0, 0);
        assert!(matches!(action, YesNoAction::Ignore));
    }
}
